'use client';

import {
  useLayoutEffect,
  useEffect,
  useRef,
  useState,
  type KeyboardEvent,
} from 'react';
import { usePointerDrag } from './use-pointer-drag';
import './drag-to-confirm.css';

export interface DragToConfirmProps {
  label: string;
  doneLabel: string;
  onConfirm: () => void;
  /** Clear the confirmed state. */
  resetKey?: number | string;
  className?: string;
}

const useIsomorphicLayoutEffect =
  typeof window === 'undefined' ? useEffect : useLayoutEffect;

/**
 * Slide the thumb to the end of the track to confirm; let go short and it
 * snaps back. The thumb is a slider for keyboards (arrow keys, End), and a
 * labelled button below confirms with two taps.
 */
export function DragToConfirm({
  label,
  doneLabel,
  onConfirm,
  resetKey = 0,
  className = '',
}: DragToConfirmProps) {
  const track = useRef<HTMLDivElement>(null);
  const [travel, setTravel] = useState(0);
  const [value, setValue] = useState(0);
  const [dragging, setDragging] = useState(false);
  const [done, setDone] = useState(false);
  const [armed, setArmed] = useState(false);
  const startValue = useRef(0);
  const latest = useRef(0);
  latest.current = value;

  useIsomorphicLayoutEffect(() => {
    const el = track.current;
    if (!el) return;
    const measure = () => setTravel(el.clientWidth - 52);
    measure();
    if (typeof ResizeObserver === 'undefined') return;
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    setDone(false);
    setValue(0);
    setArmed(false);
  }, [resetKey]);

  const confirm = () => {
    setValue(1);
    setDone(true);
    setArmed(false);
    onConfirm();
  };

  const drag = usePointerDrag({
    onStart: () => {
      if (done) return false;
      startValue.current = value;
      setDragging(true);
    },
    onMove: ({ dx }) =>
      setValue(
        Math.max(0, Math.min(1, startValue.current + dx / Math.max(1, travel)))
      ),
    onEnd: (_, cancelled) => {
      setDragging(false);
      if (!cancelled && latest.current >= 0.92) confirm();
      else setValue(0);
    },
  });

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (done) return;
    const step = {
      ArrowRight: 0.25,
      ArrowUp: 0.25,
      ArrowLeft: -0.25,
      ArrowDown: -0.25,
    }[event.key];
    if (event.key === 'End') {
      event.preventDefault();
      confirm();
    } else if (event.key === 'Home') {
      event.preventDefault();
      setValue(0);
    } else if (step !== undefined) {
      event.preventDefault();
      const next = Math.max(0, Math.min(1, value + step));
      if (next >= 1) confirm();
      else setValue(next);
    }
  };

  return (
    <div
      className={`mg-dragok ${className}`}
      data-done={done}
      data-dragging={dragging}
    >
      <div ref={track} className='mg-dragok__track'>
        <span
          className='mg-dragok__fill'
          style={{ width: 52 + value * travel }}
          aria-hidden='true'
        />
        <span className='mg-dragok__text' aria-hidden='true'>
          {done ? `✓ ${doneLabel}` : `${label} →`}
        </span>
        <div
          role='slider'
          tabIndex={done ? -1 : 0}
          aria-label={label}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={Math.round(value * 100)}
          aria-valuetext={done ? doneLabel : `${Math.round(value * 100)}%`}
          aria-disabled={done}
          className='mg-dragok__thumb'
          style={{ transform: `translateX(${value * travel}px)` }}
          onKeyDown={onKeyDown}
          {...drag}
        >
          <span aria-hidden='true'>{done ? '✓' : '›'}</span>
        </div>
      </div>
      {!done ? (
        <button
          type='button'
          className='mg-dragok__alt'
          onClick={() => (armed ? confirm() : setArmed(true))}
          onBlur={() => setArmed(false)}
        >
          {armed ? 'Tap again to confirm' : 'Confirm without sliding'}
        </button>
      ) : null}
      <span className='mg-dragok__sr' role='status'>
        {done ? doneLabel : ''}
      </span>
    </div>
  );
}

.mg-dragok {
  display: grid;
  gap: 8px;
  justify-items: center;
  width: 100%;
}

.mg-dragok__track {
  position: relative;
  width: 100%;
  height: 56px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--mg-raised, #1b1b1b);
  box-shadow: inset 0 0 0 1px var(--mg-line, #303030);
}

.mg-dragok__fill {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  border-radius: 999px;
  background: var(--mg-accent, #0047ff);
  opacity: 0.18;
  transition: width 320ms cubic-bezier(0.3, 1.4, 0.5, 1);
}

.mg-dragok__text {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  padding-left: 40px;
  color: var(--mg-text, #ffffff);
  font-weight: 600;
  pointer-events: none;
}

.mg-dragok__thumb {
  position: absolute;
  top: 2px;
  left: 2px;
  display: grid;
  place-items: center;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: var(--mg-accent, #0047ff);
  color: #fff;
  font-size: 26px;
  font-weight: 700;
  cursor: grab;
  touch-action: pan-y;
  transition: transform 320ms cubic-bezier(0.3, 1.4, 0.5, 1);
}

.mg-dragok[data-dragging='true'] .mg-dragok__thumb,
.mg-dragok[data-dragging='true'] .mg-dragok__fill {
  cursor: grabbing;
  transition: none;
}

.mg-dragok__thumb:focus-visible {
  outline: 3px solid var(--mg-text, #ffffff);
  outline-offset: 2px;
}

.mg-dragok[data-done='true'] .mg-dragok__fill {
  opacity: 1;
  background: var(--mg-accent, #0047ff);
}

.mg-dragok[data-done='true'] .mg-dragok__thumb {
  background: var(--mg-raised, #262626);
  cursor: default;
}

.mg-dragok[data-done='true'] .mg-dragok__text {
  padding: 0 60px 0 0;
}

.mg-dragok__alt {
  min-height: 40px;
  padding: 0 10px;
  border: 0;
  background: none;
  color: var(--mg-accent-text, #648aff);
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 3px;
  cursor: pointer;
}

.mg-dragok__alt:focus-visible {
  outline: 2px solid var(--mg-accent-text, #648aff);
}

.mg-dragok__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
}

@media (prefers-reduced-motion: reduce) {
  .mg-dragok__thumb,
  .mg-dragok__fill {
    transition: none;
  }
}

'use client';

import { useRef, type PointerEvent as ReactPointerEvent } from 'react';

export interface DragState {
  /** Distance from where the drag started, in pixels. */
  dx: number;
  dy: number;
  /** Pointer position in viewport coordinates. */
  clientX: number;
  clientY: number;
  /** Smoothed velocity in pixels per millisecond. */
  vx: number;
  vy: number;
}

export interface PointerDragOptions {
  /** Return false to ignore this press. */
  onStart?: (event: ReactPointerEvent<HTMLElement>) => boolean | void;
  onMove?: (drag: DragState) => void;
  /**
   * `cancelled` is true when the browser took the gesture over, for example
   * to scroll the page on touch.
   */
  onEnd?: (drag: DragState, cancelled: boolean) => void;
}

interface Active {
  id: number;
  startX: number;
  startY: number;
  lastX: number;
  lastY: number;
  lastTime: number;
  vx: number;
  vy: number;
}

/**
 * Pointer-capture dragging for mouse, pen and touch. Spread the returned
 * handlers on the element that starts the drag. Pair it with a CSS
 * `touch-action` that leaves the scroll axis you still want to the browser.
 */
export function usePointerDrag(options: PointerDragOptions) {
  const latest = useRef(options);
  latest.current = options;
  const active = useRef<Active | null>(null);

  const snapshot = (a: Active, x: number, y: number): DragState => ({
    dx: x - a.startX,
    dy: y - a.startY,
    clientX: x,
    clientY: y,
    vx: a.vx,
    vy: a.vy,
  });

  const finish = (
    event: ReactPointerEvent<HTMLElement>,
    cancelled: boolean
  ) => {
    const a = active.current;
    if (!a || a.id !== event.pointerId) return;
    active.current = null;
    if (event.currentTarget.hasPointerCapture?.(event.pointerId))
      event.currentTarget.releasePointerCapture(event.pointerId);
    // A pause before release means the pointer was not really flung.
    if (event.timeStamp - a.lastTime > 150) {
      a.vx = 0;
      a.vy = 0;
    }
    latest.current.onEnd?.(
      snapshot(a, event.clientX, event.clientY),
      cancelled
    );
  };

  return {
    onPointerDown(event: ReactPointerEvent<HTMLElement>) {
      if (event.button !== 0 || active.current) return;
      if (latest.current.onStart?.(event) === false) return;
      event.currentTarget.setPointerCapture?.(event.pointerId);
      active.current = {
        id: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        lastX: event.clientX,
        lastY: event.clientY,
        lastTime: event.timeStamp,
        vx: 0,
        vy: 0,
      };
    },
    onPointerMove(event: ReactPointerEvent<HTMLElement>) {
      const a = active.current;
      if (!a || a.id !== event.pointerId) return;
      const dt = Math.max(1, event.timeStamp - a.lastTime);
      a.vx = a.vx * 0.6 + ((event.clientX - a.lastX) / dt) * 0.4;
      a.vy = a.vy * 0.6 + ((event.clientY - a.lastY) / dt) * 0.4;
      a.lastX = event.clientX;
      a.lastY = event.clientY;
      a.lastTime = event.timeStamp;
      latest.current.onMove?.(snapshot(a, event.clientX, event.clientY));
    },
    onPointerUp(event: ReactPointerEvent<HTMLElement>) {
      finish(event, false);
    },
    onPointerCancel(event: ReactPointerEvent<HTMLElement>) {
      finish(event, true);
    },
  };
}
